const MOD = 998244353;
const MODF = MOD;
const SHRT = 1 << 16;
const G = 3.0;
const MAXSIZ = 1 << 20;

function trunc(x) {
    return x < 0 ? Math.ceil(x) : Math.floor(x);
}

function fmod(x) {
    return x - MODF * trunc(x / MODF);
}

function mod_prod(a, b) {
    return fmod(
        trunc(a / SHRT) * fmod(b * SHRT) +
        (a - SHRT * trunc(a / SHRT)) * b
    );
}

function fpow(a, b) {
    let r = 1.0;
    while (b) {
        if (b & 1) r = mod_prod(r, a);
        if (b > 1) a = mod_prod(a, a);
        b >>= 1;
    }
    return r;
}

