const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let ptr = 0;
const n = input[ptr++];
const k = input[ptr++];

let f = new Array(MAXSIZ);
for (let i = 0; i < MAXSIZ; i++) f[i] = 0.0;

for (let i = 0; i < k; i++) {
    const d = input[ptr++];
    f[d] = 1.0;
}

const m = MAXSIZ;
const m2 = m / 2;

let w = new Array(m2);
for (let i = 0; i < m2; i++) w[i] = 1.0;
w[1] = fpow(G, (MOD - 1) / m);
for (let i = 2; i < m2; i++) {
    w[i] = mod_prod(w[i - 1], w[1]);
}

let rev = new Array(m);
rev[0] = 0;
for (let i = 1; i < m; i++) {
    rev[i] = rev[i >> 1] >> 1;
    if (i & 1) rev[i] |= m2;
}

function ntt_transform(a) {
    for (let i = 0; i < m; i++) {
        if (i < rev[i]) {
            const tmp = a[i];
            a[i] = a[rev[i]];
            a[rev[i]] = tmp;
        }
    }
    let l = 2;
    while (l <= m) {
        const half = l >> 1;
        const diff = m / l;
        for (let i = 0; i < m; i += l) {
            let pw = 0;
            for (let j = i; j < i + half; j++) {
                const v = mod_prod(a[j + half], w[pw]);
                a[j + half] = a[j] - v;
                a[j] = a[j] + v;
                pw += diff;
            }
        }
        l <<= 1;
    }
}

